            <div className="art:mt-3 art:flex art:items-center art:justify-between art:rounded-xl art:bg-background/70 art:p-2">
              <p className="art:pl-3 art:text-muted-foreground art:text-sm">
                {index + 1}
                {" of "}
                {stories.length}
              </p>
              <div className="art:flex art:gap-2">
                <motion.button type="button" className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:border art:border-border art:bg-card art:text-foreground art:hover:border-border art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:size-9 art:h-9 art:rounded-full" tabIndex={0} aria-label="Previous customer story" onClick={() => setIndex((current) => (current + stories.length - 1) % stories.length)} whileHover={reduceButtonMotion ? undefined : { scale: 1.01 }} whileTap={reduceButtonMotion ? undefined : { scale: 0.99 }} transition={ARTEMIS_SPRING_PRESS}>
